def solve(x):
    import configparser

    config = configparser.ConfigParser()
    config.read_string(x)

    last_values = {}
    for section in config.sections():
        for key, value in config[section].items():
            if key == 'value':
                last_values[section] = int(value)

    result = []
    seen = set()
    for section in config.sections():
        label = next((k for k in config[section].keys() if k != 'value'), None)
        if label and label not in seen:
            seen.add(label)
            if last_values.get(section, 0) >= 8:
                result.append(label)

    return result
